class UpdateTagEndOfValidityTest : public MultiClientTestFixture {
 protected:
  ////////////////////////////////////////////////////////////////////////////////
  /// @return The name of a new tag with every field away from its default
  ////////////////////////////////////////////////////////////////////////////////
  std::string createTag() {
    const std::string tagName = uniqueTagName("update_eov");
    TagDto tag(tagName, "run-lumi", "updateTagEndOfValidity test tag");
    tag.setObjectType("JSON");
    tag.setSynchronization("SV");
    tag.setStatus("LOCKED");
    tag.setLastValidatedTime(777);
    tag.setEndOfValidity(42);
    myCrestApi->createTag(tag);
    return tagName;
  }

  void storeOne(const std::string &tagName, uint64_t since) {
    StoreSetDto input;
    input.push_back(StoreDto(since, "", "payload " + std::to_string(since)));
    myCrestApi->storeData(tagName, input, "JSON", "test", "none", "1", 0);
  }

  std::string tagFile(const std::string &tagName) const {
    return connectionString + "/tags/" + tagName + "/tag.json";
  }

  std::string iovFile(const std::string &tagName) const {
    return connectionString + "/tags/" + tagName + "/iovs.json";
  }

  static std::string readFile(const std::string &path) {
    std::ifstream in(path, std::ios::binary);
    std::stringstream buf;
    buf << in.rdbuf();
    return buf.str();
  }

  bool isServer() const { return storage == "CrestServer"; }
}

