TEST_P(UpdateTagEndOfValidityTest, SetsValueAndKeepsOtherFields) {
  const std::string tagName = createTag();
  const TagDto before = myCrestApi->findTag(tagName);

  myCrestApi->updateTagEndOfValidity(tagName, 1000);

  const TagDto after = myCrestApi->findTag(tagName);
  EXPECT_EQ(after.getEndOfValidity(), 1000u);
  EXPECT_EQ(after.getSynchronization(), before.getSynchronization());
  EXPECT_EQ(after.getDescription(), before.getDescription());
  EXPECT_EQ(after.getTimeType(), before.getTimeType());
  EXPECT_EQ(after.getObjectType(), before.getObjectType());
  EXPECT_EQ(after.getLastValidatedTime(), before.getLastValidatedTime());
  EXPECT_EQ(after.getStatus(), before.getStatus());
  // Every field above starts away from its TagDto default, so no check passes
  // by both sides holding the default.
  EXPECT_EQ(before.getSynchronization(), "SV");
  EXPECT_EQ(before.getDescription(), "updateTagEndOfValidity test tag");
  EXPECT_EQ(before.getTimeType(), "run-lumi");
  EXPECT_EQ(before.getObjectType(), "JSON");
  EXPECT_EQ(before.getLastValidatedTime(), 777u);
  EXPECT_EQ(before.getStatus(), "LOCKED");
}

TEST_P(UpdateTagEndOfValidityTest, UpdateTagWithPartialDtoResetsOtherFields) {
  const std::string tagName = createTag();
  const TagDto before = myCrestApi->findTag(tagName);
  TagDto partial;
  partial.setName(tagName);
  partial.setTimeType(before.getTimeType());
  partial.setObjectType(before.getObjectType());
  partial.setDescription(before.getDescription());
  partial.setEndOfValidity(1000);

  myCrestApi->updateTag(partial);

  const TagDto after = myCrestApi->findTag(tagName);
  EXPECT_EQ(after.getEndOfValidity(), 1000u);
  EXPECT_NE(after.getSynchronization(), before.getSynchronization());
  EXPECT_NE(after.getLastValidatedTime(), before.getLastValidatedTime());
  if (!isServer()) {
    // The server ignores status in PUT /tags.
    EXPECT_NE(after.getStatus(), before.getStatus());
  }
}

TEST_P(UpdateTagEndOfValidityTest, RoundTripsFullRange) {
  const std::string tagName = createTag();
  for (const uint64_t eov :
       {uint64_t{0}, uint64_t{1700000000000000000},
        static_cast<uint64_t>(std::numeric_limits<int64_t>::max()),
        std::numeric_limits<uint64_t>::max()}) {
    myCrestApi->updateTagEndOfValidity(tagName, eov);
    EXPECT_EQ(myCrestApi->findTag(tagName).getEndOfValidity(), eov);
  }
}

TEST_P(UpdateTagEndOfValidityTest, MissingTagThrows) {
  const std::string tagName = uniqueTagName("update_eov_missing");

  EXPECT_THROW(myCrestApi->updateTagEndOfValidity(tagName, 1000),
               CrestException);
  EXPECT_THROW(myCrestApi->findTag(tagName), CrestException);
}

TEST_P(UpdateTagEndOfValidityTest, LaterStoreData) {
  const std::string tagName = createTag();
  myCrestApi->updateTagEndOfValidity(tagName, 1000);

  storeOne(tagName, 1);

  // The server writes storeData's endTime as the end of validity. The file
  // storage ignores it.
  const uint64_t expected = isServer() ? 0 : 1000;
  EXPECT_EQ(myCrestApi->findTag(tagName).getEndOfValidity(), expected);
}

TEST_P(UpdateTagEndOfValidityTest, FsLeavesIovsUntouched) {
  if (isServer()) {
    GTEST_SKIP() << "file storage check";
  }
  const std::string tagName = createTag();
  storeOne(tagName, 1);
  storeOne(tagName, 2);
  const std::string iovsBefore = readFile(iovFile(tagName));
  ASSERT_FALSE(iovsBefore.empty());

  myCrestApi->updateTagEndOfValidity(tagName, 1000);
  EXPECT_EQ(readFile(iovFile(tagName)), iovsBefore);

  // A client in another process, with nothing in memory yet.
  CrestApiFs fresh(true, connectionString);
  fresh.updateTagEndOfValidity(tagName, 2000);
  storeOne(tagName, 3);

  EXPECT_EQ(myCrestApi->getSize(tagName), 3);
  EXPECT_EQ(myCrestApi->findTag(tagName).getEndOfValidity(), 2000u);
}

TEST_P(UpdateTagEndOfValidityTest, FsKeepsKeysTagDtoDoesNotModel) {
  if (isServer()) {
    GTEST_SKIP() << "file storage check";
  }
  const std::string tagName = createTag();
  nlohmann::json js = nlohmann::json::parse(readFile(tagFile(tagName)));
  js["extraKey"] = "kept";
  std::ofstream(tagFile(tagName)) << js.dump();

  myCrestApi->updateTagEndOfValidity(tagName, 1000);

  const nlohmann::json after =
      nlohmann::json::parse(readFile(tagFile(tagName)));
  EXPECT_EQ(after.value("extraKey", ""), "kept");
  EXPECT_EQ(after.value<uint64_t>("endOfValidity", 0), 1000u);
}

TEST_P(UpdateTagEndOfValidityTest, FsThrowsWithoutRewriteMode) {
  if (isServer()) {
    GTEST_SKIP() << "rewrite mode is a file storage setting";
  }
  const std::string tagName = createTag();
  const std::string tagBefore = readFile(tagFile(tagName));

  CrestApiFs noRewrite(false, connectionString);
  EXPECT_THROW(noRewrite.updateTagEndOfValidity(tagName, 1000), CrestException);

  EXPECT_EQ(readFile(tagFile(tagName)), tagBefore);
}

TEST_P(UpdateTagEndOfValidityTest, FsFailedWriteThrowsAndKeepsTagFile) {
  if (isServer()) {
    GTEST_SKIP() << "file storage check";
  }
  const std::string tagName = createTag();
  const std::string tagBefore = readFile(tagFile(tagName));
  // A directory at the temp path makes the open fail, even as root.
  const std::string tmpPath = tagFile(tagName) + ".tmp";
  std::filesystem::create_directory(tmpPath);

  EXPECT_THROW(myCrestApi->updateTagEndOfValidity(tagName, 1000),
               CrestException);

  EXPECT_EQ(readFile(tagFile(tagName)), tagBefore);
  std::filesystem::remove(tmpPath);
}
